269	      background-position: 0% 0%;
270	    }
271	    100% {
272	      background-position: 0% 100%;
273	    }
274	  }
275	
276	  @keyframes rotate {
277	    from {
278	      transform: rotate(0deg);
279	    }
280	    to {
281	      transform: rotate(360deg);
282	    }
283	  }
284	
285	  @keyframes particle {
286	    0% {
287	      transform: translateY(100vh) scale(0);
288	      opacity: 0;
289	    }
290	    10% {
291	      opacity: 1;
292	    }
293	    90% {
294	      opacity: 1;
295	    }
296	    100% {
297	      transform: translateY(-100vh) scale(1);
298	      opacity: 0;
299	    }
300	  }
301	
302	  @keyframes text-shimmer {
303	    0% {
304	      background-position: -200% center;
305	    }
306	    100% {
307	      background-position: 200% center;
308	    }
309	  }
310	
311	  @keyframes chromatic {
312	    0% {
313	      text-shadow:
314	        -2px 0 #ff0080,
315	        2px 0 #00f0ff;
316	    }
317	    50% {
318	      text-shadow:
319	        2px 0 #ff0080,
320	        -2px 0 #00f0ff;
321	    }
322	    100% {
323	      text-shadow: 0 0 transparent;
324	    }
325	  }
326	
327	  @keyframes blink {
328	    0%,
329	    50% {
330	      opacity: 1;
331	    }
332	    51%,
333	    100% {
334	      opacity: 0;
335	    }
336	  }
337	
338	  @keyframes spin-slow {
339	    from {
340	      transform: rotate(0deg);
341	    }
342	    to {
343	      transform: rotate(360deg);
344	    }
345	  }
346	}
347	
348	/* ============================================
349	   BASE STYLES
350	   ============================================ */
351	html {
352	  scroll-behavior: smooth;
353	}
354	
355	body {
356	  background-color: var(--color-background);
357	  color: var(--color-text-main);
358	  font-family:
359	    "Inter",
360	    system-ui,
361	    -apple-system,
362	    sans-serif;
363	  overflow-x: hidden;
364	  min-height: 100vh;
365	}
366	
367	/* ============================================
368	   CYBER GRID BACKGROUND
369	   ============================================ */
370	body::before {
371	  content: "";
372	  position: fixed;
373	  top: 0;
374	  left: 0;
375	  right: 0;
376	  bottom: 0;
377	  background-image:
378	    linear-gradient(var(--color-grid) 1px, transparent 1px),
379	    linear-gradient(90deg, var(--color-grid) 1px, transparent 1px);
380	  background-size: 60px 60px;
381	  mask-image: radial-gradient(ellipse 80% 80% at 50% 50%, black 20%, transparent 70%);
382	  pointer-events: none;
383	  z-index: 0;
384	}
385	
386	/* ============================================
387	   GLITCH TEXT EFFECT
388	   ============================================ */
389	.glitch-text {
390	  position: relative;
391	  display: inline-block;
392	}
393	
394	.glitch-text::before,
395	.glitch-text::after {
396	  content: attr(data-text);
397	  position: absolute;
398	  top: 0;
399	  left: 0;
400	  width: 100%;
401	  height: 100%;
402	  opacity: 0;
403	}
404	
405	.glitch-text:hover::before {
406	  animation: glitch-1 0.3s cubic-bezier(0.25, 0.46, 0.45, 0.94) both infinite;
407	  color: var(--color-primary);
408	  z-index: -1;
409	  opacity: 0.8;
410	}
411	
412	.glitch-text:hover::after {
413	  animation: glitch-2 0.3s cubic-bezier(0.25, 0.46, 0.45, 0.94) reverse both infinite;
414	  color: var(--color-accent);
415	  z-index: -2;
416	  opacity: 0.8;
417	}
418	
419	@keyframes glitch-1 {
420	  0%,
421	  100% {
422	    clip-path: inset(50% 0 30% 0);
423	    transform: translate(-3px, -1px);
424	  }
425	  25% {
426	    clip-path: inset(20% 0 60% 0);
427	    transform: translate(3px, 1px);
428	  }
429	  50% {
430	    clip-path: inset(70% 0 10% 0);
431	    transform: translate(-2px, 2px);
432	  }
433	  75% {
434	    clip-path: inset(10% 0 80% 0);
435	    transform: translate(2px, -2px);
436	  }
437	}
438	
439	@keyframes glitch-2 {
440	  0%,
441	  100% {
442	    clip-path: inset(30% 0 50% 0);
443	    transform: translate(3px, 1px);
444	  }
445	  25% {
446	    clip-path: inset(60% 0 20% 0);
447	    transform: translate(-3px, -1px);
448	  }
449	  50% {
450	    clip-path: inset(10% 0 70% 0);
451	    transform: translate(2px, -2px);
452	  }
453	  75% {
454	    clip-path: inset(80% 0 10% 0);
455	    transform: translate(-2px, 2px);
456	  }
457	}
458	
459	/* ============================================
460	   SCAN LINE EFFECT
461	   ============================================ */
462	.scan-line {
463	  position: fixed;
464	  left: 0;
465	  right: 0;
466	  height: 2px;
467	  background: linear-gradient(
468	    90deg,
469	    transparent,
470	    var(--color-primary) 20%,
471	    var(--color-secondary) 50%,
472	    var(--color-primary) 80%,
473	    transparent
474	  );
475	  opacity: 0.6;
476	  animation: scan-line 6s linear infinite;
477	  pointer-events: none;
478	  z-index: 100;
479	  box-shadow:
480	    0 0 20px var(--color-primary),
481	    0 0 60px var(--color-primary);
482	}
483	
484	/* ============================================
485	   CYBER CARD STYLES
486	   ============================================ */
487	.cyber-card {
488	  position: relative;
489	  background: linear-gradient(135deg, rgba(10, 10, 16, 0.95) 0%, rgba(5, 5, 8, 0.95) 100%);
490	  border: 1px solid rgba(0, 240, 255, 0.1);
491	  backdrop-filter: blur(20px);
492	  overflow: hidden;
493	}
494	
495	.cyber-card::before {
496	  content: "";
497	  position: absolute;
498	  inset: 0;
499	  background: linear-gradient(
500	    135deg,
501	    rgba(0, 240, 255, 0.1) 0%,
502	    transparent 50%,
503	    rgba(191, 0, 255, 0.05) 100%
504	  );
505	  opacity: 0;
506	  transition: opacity 0.5s ease;
507	}
508	
509	.cyber-card:hover::before {
510	  opacity: 1;
511	}
512	
513	/* Animated border on hover */
514	.cyber-card::after {
515	  content: "";
516	  position: absolute;
517	  inset: 0;
518	  padding: 1px;
519	  background: linear-gradient(
520	    90deg,
521	    var(--color-primary),
522	    rgba(0, 240, 255, 0.4),
523	    var(--color-primary)
524	  );
525	  background-size: 300% 100%;
526	  z-index: 0;
527	  opacity: 0;
528	  transition: opacity 0.3s ease;
529	  animation: border-flow 4s linear infinite;
530	  mask:
531	    linear-gradient(#fff 0 0) content-box,
532	    linear-gradient(#fff 0 0);
533	  mask-composite: exclude;
534	  pointer-events: none;
535	}
536	
537	.cyber-card:hover::after {
538	  opacity: 1;
539	}
540	
541	/* ============================================
542	   HUD CORNERS
543	   ============================================ */
544	.hud-corners {
545	  position: relative;
546	}
547	
548	.hud-corners::before,
549	.hud-corners::after {
550	  content: "";
551	  position: absolute;
552	  width: 20px;
553	  height: 20px;
554	  transition: all 0.3s ease;
555	}
556	
557	.hud-corners::before {
558	  top: -1px;
559	  left: -1px;
560	  border-left: 2px solid var(--color-primary);
561	  border-top: 2px solid var(--color-primary);
562	  opacity: 0.5;
563	}
564	
565	.hud-corners::after {
566	  bottom: -1px;
567	  right: -1px;
568	  border-right: 2px solid var(--color-secondary);
569	  border-bottom: 2px solid var(--color-secondary);
570	  opacity: 0.5;
571	}
572	
573	.hud-corners:hover::before,
574	.hud-corners:hover::after {
575	  width: 30px;
576	  height: 30px;
577	  opacity: 1;
578	}
579	
580	/* ============================================
581	   GLOWING TEXT
582	   ============================================ */
583	.glow-text {
584	  text-shadow:
585	    0 0 10px currentColor,
586	    0 0 20px currentColor,
587	    0 0 40px currentColor,
588	    0 0 80px currentColor;
589	}
590	
591	.glow-text-subtle {
592	  text-shadow:
593	    0 0 10px currentColor,
594	    0 0 20px currentColor;
595	}
596	
597	/* Chromatic aberration on hover */
598	.chromatic-hover:hover {
599	  animation: chromatic 0.3s ease-out;
600	}
601	
602	/* ============================================
603	   ANIMATED GRADIENT BORDER
604	   ============================================ */
605	.gradient-border {
606	  position: relative;
607	  background: var(--color-surface);
608	}
609	
610	.gradient-border::before {
611	  content: "";
612	  position: absolute;
613	  inset: 0;
614	  padding: 1px;
615	  background: linear-gradient(
616	    90deg,
617	    var(--color-primary),
618	    var(--color-secondary),
619	    var(--color-accent),
620	    var(--color-primary)
621	  );
622	  background-size: 300% 100%;
623	  animation: border-flow 4s linear infinite;
624	  mask:
625	    linear-gradient(#fff 0 0) content-box,
626	    linear-gradient(#fff 0 0);
627	  mask-composite: exclude;
628	  pointer-events: none;
629	  border-radius: inherit;
630	}
631	
632	/* ============================================
633	   TERMINAL STYLES
634	   ============================================ */
635	.terminal-text {
636	  font-family: "JetBrains Mono", "Fira Code", "SF Mono", "Consolas", monospace;
637	  letter-spacing: 0.05em;
638	}
639	
640	.typing-cursor::after {
641	  content: "|";
642	  animation: blink 1s step-end infinite;
643	  color: var(--color-primary);
644	  margin-left: 2px;
645	}
646	
647	/* ============================================
648	   STATUS INDICATOR
649	   ============================================ */
650	.status-dot {
651	  width: 8px;
652	  height: 8px;
653	  border-radius: 50%;
654	  background: var(--color-neon-green);
655	  box-shadow:
656	    0 0 10px var(--color-neon-green),
657	    0 0 20px var(--color-neon-green),
658	    0 0 30px var(--color-neon-green);
659	  animation: flicker 3s ease-in-out infinite;
660	}
661	
662	/* ============================================
663	   HOLOGRAPHIC EFFECT
664	   ============================================ */
665	.holographic {
666	  background: linear-gradient(
667	    135deg,
668	    rgba(0, 240, 255, 0.15) 0%,
669	    rgba(191, 0, 255, 0.15) 25%,
670	    rgba(255, 0, 128, 0.15) 50%,
671	    rgba(0, 255, 136, 0.15) 75%,
672	    rgba(0, 240, 255, 0.15) 100%
673	  );
674	  background-size: 400% 400%;
675	  animation: border-flow 8s ease infinite;
676	}
677	
678	/* ============================================
679	   SHIMMER TEXT
680	   ============================================ */
681	.shimmer-text {
682	  background: linear-gradient(
683	    90deg,
684	    var(--color-text-main) 0%,
685	    var(--color-primary) 25%,
686	    var(--color-secondary) 50%,
687	    var(--color-primary) 75%,
688	    var(--color-text-main) 100%
689	  );
690	  background-size: 200% auto;
691	  background-clip: text;
692	  -webkit-background-clip: text;
693	  -webkit-text-fill-color: transparent;
694	  animation: text-shimmer 3s linear infinite;
695	}
696	
697	/* ============================================
698	   NEON BUTTON
699	   ============================================ */
700	.neon-button {
701	  position: relative;
702	  padding: 1rem 2rem;
703	  background: transparent;
704	  border: 1px solid var(--color-primary);
705	  color: var(--color-primary);
706	  font-family: "JetBrains Mono", monospace;
707	  text-transform: uppercase;
708	  letter-spacing: 0.1em;
709	  cursor: pointer;
710	  overflow: hidden;
711	  transition: all 0.3s ease;
712	}
713	
714	.neon-button::before {
715	  content: "";
716	  position: absolute;
717	  top: 0;
718	  left: -100%;
719	  width: 100%;
720	  height: 100%;
721	  background: linear-gradient(90deg, transparent, rgba(0, 240, 255, 0.4), transparent);
722	  transition: left 0.5s ease;
723	}
724	
725	.neon-button:hover {
726	  background: rgba(0, 240, 255, 0.1);
727	  box-shadow:
728	    0 0 20px rgba(0, 240, 255, 0.5),
729	    inset 0 0 20px rgba(0, 240, 255, 0.1);
730	  text-shadow: 0 0 10px var(--color-primary);
731	}
732	
733	.neon-button:hover::before {
734	  left: 100%;
735	}
736	
737	/* ============================================
738	   CRT SCREEN EFFECT
739	   ============================================ */
740	.crt-effect {
741	  position: relative;
742	}
743	
744	.crt-effect::before {
745	  content: "";
746	  position: absolute;
747	  inset: 0;
748	  background: repeating-linear-gradient(
749	    0deg,
750	    rgba(0, 0, 0, 0.15),
751	    rgba(0, 0, 0, 0.15) 1px,
752	    transparent 1px,
753	    transparent 2px
754	  );
755	  pointer-events: none;
756	  z-index: 10;
757	}
758	
759	/* ============================================
760	   MAGNETIC HOVER AREA
761	   ============================================ */
762	.magnetic-area {
763	  transition: transform 0.3s cubic-bezier(0.175, 0.885, 0.32, 1.275);
764	}
765	
766	/* ============================================
767	   CUSTOM SCROLLBAR
768	   ============================================ */
769	::-webkit-scrollbar {
770	  width: 8px;
771	  height: 8px;
772	}
773	
774	::-webkit-scrollbar-track {
775	  background: var(--color-background);
776	  border-left: 1px solid rgba(0, 240, 255, 0.1);
777	}
778	
779	::-webkit-scrollbar-thumb {
780	  background: linear-gradient(180deg, var(--color-primary), var(--color-secondary));
781	  border-radius: 0;
782	}
783	
784	::-webkit-scrollbar-thumb:hover {
785	  background: linear-gradient(180deg, var(--color-primary), var(--color-accent));
786	  box-shadow: 0 0 10px var(--color-primary);
787	}
788	
789	/* ============================================
790	   SELECTION COLOR
791	   ============================================ */
792	::selection {
793	  background: rgba(0, 240, 255, 0.3);
794	  color: var(--color-text-main);
795	  text-shadow: none;
796	}
797	
798	/* ============================================
799	   LINK STYLES
800	   ============================================ */
801	.cyber-link {
802	  position: relative;
803	  color: var(--color-primary);
804	  text-decoration: none;
805	  transition: all 0.3s ease;
806	}
807	
808	.cyber-link::after {
809	  content: "";
810	  position: absolute;
811	  bottom: -2px;
812	  left: 0;
813	  width: 0;
814	  height: 1px;
815	  background: var(--color-primary);
816	  box-shadow: 0 0 10px var(--color-primary);
817	  transition: width 0.3s ease;
818	}
819	
820	.cyber-link:hover::after {
821	  width: 100%;
822	}
823	
824	/* ============================================
825	   GLASS MORPHISM
826	   ============================================ */
827	.glass {
828	  background: rgba(10, 10, 16, 0.7);
829	  backdrop-filter: blur(20px);
830	  border: 1px solid rgba(255, 255, 255, 0.05);
831	}
832	
833	/* ============================================
834	   3D PERSPECTIVE CONTAINER
835	   ============================================ */
836	.perspective-container {
837	  perspective: 1000px;
838	  transform-style: preserve-3d;
839	}
840	
841	/* ============================================
842	   PULSE RING
843	   ============================================ */
844	.pulse-ring {
845	  position: relative;
846	}
847	
848	.pulse-ring::before {
849	  content: "";
850	  position: absolute;
851	  inset: -4px;
852	  border: 2px solid var(--color-primary);
853	  border-radius: inherit;
854	  animation: pulse-ring 2s ease-out infinite;
855	  opacity: 0;
856	}
857	
858	@keyframes pulse-ring {
859	  0% {
860	    transform: scale(1);
861	    opacity: 0.5;
862	  }
863	  100% {
864	    transform: scale(1.2);
865	    opacity: 0;
866	  }
867	}
868	
869	/* ============================================
870	   DATA STREAM BACKGROUND
871	   ============================================ */
872	.data-stream-bg {
873	  background-image: repeating-linear-gradient(
874	    0deg,
875	    transparent,
876	    transparent 2px,
877	    rgba(0, 240, 255, 0.02) 2px,
878	    rgba(0, 240, 255, 0.02) 4px
879	  );
880	  background-size: 100% 8px;
881	  animation: data-stream 30s linear infinite;
882	}
883	
884	/* ============================================
885	   RESPONSIVE UTILITIES
886	   ============================================ */
887	@media (prefers-reduced-motion: reduce) {
888	  *,
889	  *::before,
890	  *::after {
891	    animation-duration: 0.01ms !important;
892	    animation-iteration-count: 1 !important;
893	    transition-duration: 0.01ms !important;
894	  }
895	}
