@import "tailwindcss";
@plugin "@tailwindcss/typography";

@theme {
  /* Futuristic Cyber Color Palette */
  --color-background: #050508;
  --color-surface: #0a0a10;
  --color-surface-hover: #12121a;
  --color-primary: #00f0ff;
  --color-primary-hover: #00c8d4;
  --color-secondary: #bf00ff;
  --color-accent: #ff0080;
  --color-neon-green: #00ff88;
  --color-neon-yellow: #f0ff00;
  --color-warning: #ff6b00;
  --color-text-main: #e8e8ff;
  --color-text-muted: #5a5a7a;
  --color-grid: rgba(0, 240, 255, 0.02);
  --color-border-glow: rgba(0, 240, 255, 0.5);

  /* Core Animations */
  --animate-fade-in: fade-in 0.8s ease-out forwards;
  --animate-slide-up: slide-up 0.8s cubic-bezier(0.16, 1, 0.3, 1) forwards;
  --animate-slide-down: slide-down 0.8s cubic-bezier(0.16, 1, 0.3, 1) forwards;
  --animate-scale-in: scale-in 0.6s cubic-bezier(0.16, 1, 0.3, 1) forwards;
  --animate-float: float 6s ease-in-out infinite;
  --animate-float-slow: float-slow 12s ease-in-out infinite;
  --animate-float-reverse: float-reverse 10s ease-in-out infinite;
  --animate-pulse-glow: pulse-glow 3s ease-in-out infinite;
  --animate-scan-line: scan-line 6s linear infinite;
  --animate-scan-horizontal: scan-horizontal 8s linear infinite;
  --animate-glitch: glitch 0.4s ease-in-out;
  --animate-glitch-loop: glitch-loop 3s infinite;
  --animate-border-flow: border-flow 4s linear infinite;
  --animate-flicker: flicker 4s linear infinite;
  --animate-data-stream: data-stream 20s linear infinite;
  --animate-rotate: rotate 20s linear infinite;
  --animate-particle: particle 20s linear infinite;
  --animate-chromatic: chromatic 0.3s ease-out;
  --animate-text-shimmer: text-shimmer 3s linear infinite;

  @keyframes fade-in {
    from {
      opacity: 0;
      transform: translateY(20px);
    }
    to {
      opacity: 1;
      transform: translateY(0);
    }
  }

  @keyframes slide-up {
    from {
      transform: translateY(60px);
      opacity: 0;
    }
    to {
      transform: translateY(0);
      opacity: 1;
    }
  }

  @keyframes slide-down {
    from {
      transform: translateY(-60px);
      opacity: 0;
    }
    to {
      transform: translateY(0);
      opacity: 1;
    }
  }

  @keyframes scale-in {
    from {
      transform: scale(0.9);
      opacity: 0;
    }
    to {
      transform: scale(1);
      opacity: 1;
    }
  }

  @keyframes float {
    0%,
    100% {
      transform: translateY(0) rotate(0deg);
    }
    50% {
      transform: translateY(-20px) rotate(2deg);
    }
  }

  @keyframes float-slow {
    0%,
    100% {
      transform: translate(0, 0) scale(1);
    }
    33% {
      transform: translate(30px, -30px) scale(1.05);
    }
    66% {
      transform: translate(-20px, 20px) scale(0.95);
    }
  }

  @keyframes float-reverse {
    0%,
    100% {
      transform: translate(0, 0) scale(1);
    }
    33% {
      transform: translate(-40px, 20px) scale(1.1);
    }
    66% {
      transform: translate(30px, -40px) scale(0.9);
    }
  }

  @keyframes pulse-glow {
    0%,
    100% {
      opacity: 0.3;
      transform: scale(1);
      filter: blur(60px);
    }
    50% {
      opacity: 0.6;
      transform: scale(1.1);
      filter: blur(80px);
    }
  }

  @keyframes scan-line {
    0% {
      top: -10%;
      opacity: 0;
    }
    10% {
      opacity: 1;
    }
    90% {
      opacity: 1;
    }
    100% {
      top: 110%;
      opacity: 0;
    }
  }

  @keyframes scan-horizontal {
    0% {
      top: 0%;
    }
    100% {
      top: 100%;
    }
  }

  @keyframes glitch {
    0%,
    100% {
      transform: translate(0);
      filter: hue-rotate(0deg);
    }
    10% {
      transform: translate(-5px, 2px);
      filter: hue-rotate(90deg);
    }
    20% {
      transform: translate(5px, -2px);
      filter: hue-rotate(-90deg);
    }
    30% {
      transform: translate(-3px, 1px);
    }
    40% {
      transform: translate(3px, -1px);
    }
    50% {
      transform: translate(-2px, 2px);
      filter: hue-rotate(180deg);
    }
    60% {
      transform: translate(2px, -2px);
    }
    70% {
      transform: translate(-1px, 1px);
      filter: hue-rotate(-180deg);
    }
    80% {
      transform: translate(1px, -1px);
    }
    90% {
      transform: translate(0);
      filter: hue-rotate(0deg);
    }
  }

  @keyframes glitch-loop {
    0%,
    90%,
    100% {
      transform: translate(0);
      clip-path: inset(0 0 0 0);
    }
    92% {
      transform: translate(-2px, 1px);
      clip-path: inset(20% 0 60% 0);
    }
    94% {
      transform: translate(2px, -1px);
      clip-path: inset(60% 0 20% 0);
    }
    96% {
      transform: translate(-1px, 2px);
      clip-path: inset(40% 0 40% 0);
    }
    98% {
      transform: translate(1px, -2px);
      clip-path: inset(10% 0 80% 0);
    }
  }

  @keyframes border-flow {
    0% {
      background-position: 0% 50%;
    }
    50% {
      background-position: 100% 50%;
    }
    100% {
      background-position: 0% 50%;
    }
  }

  @keyframes flicker {
    0%,
    100% {
      opacity: 1;
    }
    92% {
      opacity: 1;
    }
    92.5% {
      opacity: 0.7;
    }
    93% {
      opacity: 1;
    }
    95% {
      opacity: 0.9;
    }
    95.5% {
      opacity: 1;
    }
    97% {
      opacity: 0.8;
    }
    97.5% {
      opacity: 1;
    }
  }

  @keyframes data-stream {
    0% {
      background-position: 0% 0%;
    }
    100% {
      background-position: 0% 100%;
    }
  }

  @keyframes rotate {
    from {
      transform: rotate(0deg);
    }
    to {
      transform: rotate(360deg);
    }
  }

  @keyframes particle {
    0% {
      transform: translateY(100vh) scale(0);
      opacity: 0;
    }
    10% {
      opacity: 1;
    }
    90% {
      opacity: 1;
    }
    100% {
      transform: translateY(-100vh) scale(1);
      opacity: 0;
    }
  }

  @keyframes text-shimmer {
    0% {
      background-position: -200% center;
    }
    100% {
      background-position: 200% center;
    }
  }

  @keyframes chromatic {
    0% {
      text-shadow:
        -2px 0 #ff0080,
        2px 0 #00f0ff;
    }
    50% {
      text-shadow:
        2px 0 #ff0080,
        -2px 0 #00f0ff;
    }
    100% {
      text-shadow: 0 0 transparent;
    }
  }

  @keyframes blink {
    0%,
    50% {
      opacity: 1;
    }
    51%,
    100% {
      opacity: 0;
    }
  }

  @keyframes spin-slow {
    from {
      transform: rotate(0deg);
    }
    to {
      transform: rotate(360deg);
    }
  }
}

/* ============================================
   BASE STYLES
   ============================================ */
html {
  scroll-behavior: smooth;
}

body {
  background-color: var(--color-background);
  color: var(--color-text-main);
  font-family:
    "Inter",
    system-ui,
    -apple-system,
    sans-serif;
  overflow-x: hidden;
  min-height: 100vh;
}

/* ============================================
   CYBER GRID BACKGROUND
   ============================================ */
body::before {
  content: "";
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background-image:
    linear-gradient(var(--color-grid) 1px, transparent 1px),
    linear-gradient(90deg, var(--color-grid) 1px, transparent 1px);
  background-size: 60px 60px;
  mask-image: radial-gradient(ellipse 80% 80% at 50% 50%, black 20%, transparent 70%);
  pointer-events: none;
  z-index: 0;
}

/* ============================================
   GLITCH TEXT EFFECT
   ============================================ */
.glitch-text {
  position: relative;
  display: inline-block;
}

.glitch-text::before,
.glitch-text::after {
  content: attr(data-text);
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  opacity: 0;
}

.glitch-text:hover::before {
  animation: glitch-1 0.3s cubic-bezier(0.25, 0.46, 0.45, 0.94) both infinite;
  color: var(--color-primary);
  z-index: -1;
  opacity: 0.8;
}

.glitch-text:hover::after {
  animation: glitch-2 0.3s cubic-bezier(0.25, 0.46, 0.45, 0.94) reverse both infinite;
  color: var(--color-accent);
  z-index: -2;
  opacity: 0.8;
}

@keyframes glitch-1 {
  0%,
  100% {
    clip-path: inset(50% 0 30% 0);
    transform: translate(-3px, -1px);
  }
  25% {
    clip-path: inset(20% 0 60% 0);
    transform: translate(3px, 1px);
  }
  50% {
    clip-path: inset(70% 0 10% 0);
    transform: translate(-2px, 2px);
  }
  75% {
    clip-path: inset(10% 0 80% 0);
    transform: translate(2px, -2px);
  }
}

@keyframes glitch-2 {
  0%,
  100% {
    clip-path: inset(30% 0 50% 0);
    transform: translate(3px, 1px);
  }
  25% {
    clip-path: inset(60% 0 20% 0);
    transform: translate(-3px, -1px);
  }
  50% {
    clip-path: inset(10% 0 70% 0);
    transform: translate(2px, -2px);
  }
  75% {
    clip-path: inset(80% 0 10% 0);
    transform: translate(-2px, 2px);
  }
}

/* ============================================
   SCAN LINE EFFECT
   ============================================ */
.scan-line {
  position: fixed;
  left: 0;
  right: 0;
  height: 2px;
  background: linear-gradient(
    90deg,
    transparent,
    var(--color-primary) 20%,
    var(--color-secondary) 50%,
    var(--color-primary) 80%,
    transparent
  );
  opacity: 0.6;
  animation: scan-line 6s linear infinite;
  pointer-events: none;
  z-index: 100;
  box-shadow:
    0 0 20px var(--color-primary),
    0 0 60px var(--color-primary);
}

/* ============================================
   CYBER CARD STYLES
   ============================================ */
.cyber-card {
  position: relative;
  background: linear-gradient(135deg, rgba(10, 10, 16, 0.95) 0%, rgba(5, 5, 8, 0.95) 100%);
  border: 1px solid rgba(0, 240, 255, 0.1);
  backdrop-filter: blur(20px);
  overflow: hidden;
}

.cyber-card::before {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(
    135deg,
    rgba(0, 240, 255, 0.1) 0%,
    transparent 50%,
    rgba(191, 0, 255, 0.05) 100%
  );
  opacity: 0;
  transition: opacity 0.5s ease;
}

.cyber-card:hover::before {
  opacity: 1;
}

/* Animated border on hover */
.cyber-card::after {
  content: "";
  position: absolute;
  inset: 0;
  padding: 1px;
  background: linear-gradient(
    90deg,
    var(--color-primary),
    rgba(0, 240, 255, 0.4),
    var(--color-primary)
  );
  background-size: 300% 100%;
  z-index: 0;
  opacity: 0;
  transition: opacity 0.3s ease;
  animation: border-flow 4s linear infinite;
  mask:
    linear-gradient(#fff 0 0) content-box,
    linear-gradient(#fff 0 0);
  mask-composite: exclude;
  pointer-events: none;
}

.cyber-card:hover::after {
  opacity: 1;
}

/* ============================================
   HUD CORNERS
   ============================================ */
.hud-corners {
  position: relative;
}

.hud-corners::before,
.hud-corners::after {
  content: "";
  position: absolute;
  width: 20px;
  height: 20px;
  transition: all 0.3s ease;
}

.hud-corners::before {
  top: -1px;
  left: -1px;
  border-left: 2px solid var(--color-primary);
  border-top: 2px solid var(--color-primary);
  opacity: 0.5;
}

.hud-corners::after {
  bottom: -1px;
  right: -1px;
  border-right: 2px solid var(--color-secondary);
  border-bottom: 2px solid var(--color-secondary);
  opacity: 0.5;
}

.hud-corners:hover::before,
.hud-corners:hover::after {
  width: 30px;
  height: 30px;
  opacity: 1;
}

/* ============================================
   GLOWING TEXT
   ============================================ */
.glow-text {
  text-shadow:
    0 0 10px currentColor,
    0 0 20px currentColor,
    0 0 40px currentColor,
    0 0 80px currentColor;
}

.glow-text-subtle {
  text-shadow:
    0 0 10px currentColor,
    0 0 20px currentColor;
}

/* Chromatic aberration on hover */
.chromatic-hover:hover {
  animation: chromatic 0.3s ease-out;
}

/* ============================================
   ANIMATED GRADIENT BORDER
   ============================================ */
.gradient-border {
  position: relative;
  background: var(--color-surface);
}

.gradient-border::before {
  content: "";
  position: absolute;
  inset: 0;
  padding: 1px;
  background: linear-gradient(
    90deg,
    var(--color-primary),
    var(--color-secondary),
    var(--color-accent),
    var(--color-primary)
  );
  background-size: 300% 100%;
  animation: border-flow 4s linear infinite;
  mask:
    linear-gradient(#fff 0 0) content-box,
    linear-gradient(#fff 0 0);
  mask-composite: exclude;
  pointer-events: none;
  border-radius: inherit;
}

/* ============================================
   TERMINAL STYLES
   ============================================ */
.terminal-text {
  font-family: "JetBrains Mono", "Fira Code", "SF Mono", "Consolas", monospace;
  letter-spacing: 0.05em;
}

.typing-cursor::after {
  content: "|";
  animation: blink 1s step-end infinite;
  color: var(--color-primary);
  margin-left: 2px;
}

/* ============================================
   STATUS INDICATOR
   ============================================ */
.status-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--color-neon-green);
  box-shadow:
    0 0 10px var(--color-neon-green),
    0 0 20px var(--color-neon-green),
    0 0 30px var(--color-neon-green);
  animation: flicker 3s ease-in-out infinite;
}

/* ============================================
   HOLOGRAPHIC EFFECT
   ============================================ */
.holographic {
  background: linear-gradient(
    135deg,
    rgba(0, 240, 255, 0.15) 0%,
    rgba(191, 0, 255, 0.15) 25%,
    rgba(255, 0, 128, 0.15) 50%,
    rgba(0, 255, 136, 0.15) 75%,
    rgba(0, 240, 255, 0.15) 100%
  );
  background-size: 400% 400%;
  animation: border-flow 8s ease infinite;
}

/* ============================================
   SHIMMER TEXT
   ============================================ */
.shimmer-text {
  background: linear-gradient(
    90deg,
    var(--color-text-main) 0%,
    var(--color-primary) 25%,
    var(--color-secondary) 50%,
    var(--color-primary) 75%,
    var(--color-text-main) 100%
  );
  background-size: 200% auto;
  background-clip: text;
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  animation: text-shimmer 3s linear infinite;
}

/* ============================================
   NEON BUTTON
   ============================================ */
.neon-button {
  position: relative;
  padding: 1rem 2rem;
  background: transparent;
  border: 1px solid var(--color-primary);
  color: var(--color-primary);
  font-family: "JetBrains Mono", monospace;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  cursor: pointer;
  overflow: hidden;
  transition: all 0.3s ease;
}

.neon-button::before {
  content: "";
  position: absolute;
  top: 0;
  left: -100%;
  width: 100%;
  height: 100%;
  background: linear-gradient(90deg, transparent, rgba(0, 240, 255, 0.4), transparent);
  transition: left 0.5s ease;
}

.neon-button:hover {
  background: rgba(0, 240, 255, 0.1);
  box-shadow:
    0 0 20px rgba(0, 240, 255, 0.5),
    inset 0 0 20px rgba(0, 240, 255, 0.1);
  text-shadow: 0 0 10px var(--color-primary);
}

.neon-button:hover::before {
  left: 100%;
}

/* ============================================
   CRT SCREEN EFFECT
   ============================================ */
.crt-effect {
  position: relative;
}

.crt-effect::before {
  content: "";
  position: absolute;
  inset: 0;
  background: repeating-linear-gradient(
    0deg,
    rgba(0, 0, 0, 0.15),
    rgba(0, 0, 0, 0.15) 1px,
    transparent 1px,
    transparent 2px
  );
  pointer-events: none;
  z-index: 10;
}

/* ============================================
   MAGNETIC HOVER AREA
   ============================================ */
.magnetic-area {
  transition: transform 0.3s cubic-bezier(0.175, 0.885, 0.32, 1.275);
}

/* ============================================
   CUSTOM SCROLLBAR
   ============================================ */
::-webkit-scrollbar {
  width: 8px;
  height: 8px;
}

::-webkit-scrollbar-track {
  background: var(--color-background);
  border-left: 1px solid rgba(0, 240, 255, 0.1);
}

::-webkit-scrollbar-thumb {
  background: linear-gradient(180deg, var(--color-primary), var(--color-secondary));
  border-radius: 0;
}

::-webkit-scrollbar-thumb:hover {
  background: linear-gradient(180deg, var(--color-primary), var(--color-accent));
  box-shadow: 0 0 10px var(--color-primary);
}

/* ============================================
   SELECTION COLOR
   ============================================ */
::selection {
  background: rgba(0, 240, 255, 0.3);
  color: var(--color-text-main);
  text-shadow: none;
}

/* ============================================
   LINK STYLES
   ============================================ */
.cyber-link {
  position: relative;
  color: var(--color-primary);
  text-decoration: none;
  transition: all 0.3s ease;
}

.cyber-link::after {
  content: "";
  position: absolute;
  bottom: -2px;
  left: 0;
  width: 0;
  height: 1px;
  background: var(--color-primary);
  box-shadow: 0 0 10px var(--color-primary);
  transition: width 0.3s ease;
}

.cyber-link:hover::after {
  width: 100%;
}

/* ============================================
   GLASS MORPHISM
   ============================================ */
.glass {
  background: rgba(10, 10, 16, 0.7);
  backdrop-filter: blur(20px);
  border: 1px solid rgba(255, 255, 255, 0.05);
}

/* ============================================
   3D PERSPECTIVE CONTAINER
   ============================================ */
.perspective-container {
  perspective: 1000px;
  transform-style: preserve-3d;
}

/* ============================================
   PULSE RING
   ============================================ */
.pulse-ring {
  position: relative;
}

.pulse-ring::before {
  content: "";
  position: absolute;
  inset: -4px;
  border: 2px solid var(--color-primary);
  border-radius: inherit;
  animation: pulse-ring 2s ease-out infinite;
  opacity: 0;
}

@keyframes pulse-ring {
  0% {
    transform: scale(1);
    opacity: 0.5;
  }
  100% {
    transform: scale(1.2);
    opacity: 0;
  }
}

/* ============================================
   DATA STREAM BACKGROUND
   ============================================ */
.data-stream-bg {
  background-image: repeating-linear-gradient(
    0deg,
    transparent,
    transparent 2px,
    rgba(0, 240, 255, 0.02) 2px,
    rgba(0, 240, 255, 0.02) 4px
  );
  background-size: 100% 8px;
  animation: data-stream 30s linear infinite;
}

/* ============================================
   RESPONSIVE UTILITIES
   ============================================ */
@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}

